def mindist(S,a,metric):
    Y,X=np.mgrid[0:a.shape[0],0:a.shape[1]]
    S=np.array(S)
    ys,xs=S[:,0][:,None,None],S[:,1][None,None,:]
    dy=Y[:,:,None]-ys; dx=X[:,:,None]-xs
    if metric=='man': D=np.abs(dy)+np.abs(dx)
    elif metric=='che': D=np.maximum(np.abs(dy),np.abs(dx))
    else: D=dy**2+dx**2
    return D.min(axis=2)
